/// <summary>
///     The <c>AVABPJobsUIBuilder</c> class is the UI builder class for <c>BP-Jobs</c>
/// </summary>
class AVABPJobsUIBuilder extends SysOperationAutomaticUIBuilder
{
    AVABPJobsContract   contract;

    DialogField df_KCS_KBVBuildingProjectID;
    DialogField df_UpdateBPStatus;
    DialogField df_UpdateBPStatusGLB;
    DialogField df_UpdateSalesVolume;
    DialogField df_UpdateSalesVolumeGLB;
    DialogField df_UpdateResponsibilities;
    DialogField df_CreateActivities;

}

Method.Source:
/// <summary>
///     AVA <c>getContract</c> method.
/// </summary>
/// <returns>
///     <c>AVABPJobsContract</c> as return value
/// </returns>
private AVABPJobsContract getContract()
{
    if(!contract)
    {
        contract = this.dataContractObject() as AVABPJobsContract;
    }

    return contract;
}

/// <summary>
///     AVA <c>getFromDialog</c> method.
/// </summary>
public void getFromDialog()
{
    super();

    this.getContract().parmKCS_KBVBuildingProjectID(df_KCS_KBVBuildingProjectID.value());
}

/// <summary>
///     AVA <c>postBuild</c> method.
/// </summary>
public void postBuild()
{
    super();

    // get references to dialog controls after creation
    df_KCS_KBVBuildingProjectID = this.bindInfo().getDialogField(   this.dataContractObject(),
                                                                    methodStr(AVABPJobsContract, parmKCS_KBVBuildingProjectID));
    df_UpdateBPStatus           = this.bindInfo().getDialogField(   this.dataContractObject(),
                                                                    methodStr(AVABPJobsContract, parmUpdateBPStatus));
    df_UpdateBPStatusGLB        = this.bindInfo().getDialogField(   this.dataContractObject(),
                                                                    methodStr(AVABPJobsContract, parmUpdateBPStatusGLB));
    df_UpdateSalesVolume        = this.bindInfo().getDialogField(   this.dataContractObject(),
                                                                    methodStr(AVABPJobsContract, parmUpdateSalesVolume));
    df_UpdateSalesVolumeGLB     = this.bindInfo().getDialogField(   this.dataContractObject(),
                                                                    methodStr(AVABPJobsContract, parmUpdateSalesVolumeGLB));
    df_UpdateResponsibilities   = this.bindInfo().getDialogField(   this.dataContractObject(),
                                                                    methodStr(AVABPJobsContract, parmUpdateResponsibilities));
    df_CreateActivities         = this.bindInfo().getDialogField(   this.dataContractObject(),
                                                                    methodStr(AVABPJobsContract, parmCreateActivities));


    df_KCS_KBVBuildingProjectID.enabled(df_KCS_KBVBuildingProjectID.value() == '');
}

/// <summary>
///     AVA <c>postRun</c> method.
/// </summary>
public void postRun()
{
    super();

    //modified
    df_KCS_KBVBuildingProjectID.registerOverrideMethod( methodStr(FormStringControl, modified),
                                                        methodStr(AVABPJobsUIBuilder, modifiedKCS_KBVBuildingProjectID),
                                                        this);
    df_UpdateBPStatus.registerOverrideMethod(           methodstr(FormCheckBoxControl, modified),
                                                        methodstr(AVABPJobsUIBuilder, modifiedUpdateBPStatus),
                                                        this);
    df_UpdateBPStatusGLB.registerOverrideMethod(        methodstr(FormCheckBoxControl, modified),
                                                        methodstr(AVABPJobsUIBuilder, modifiedUpdateBPStatusGLB),
                                                        this);
    df_UpdateSalesVolume.registerOverrideMethod(        methodstr(FormCheckBoxControl, modified),
                                                        methodstr(AVABPJobsUIBuilder, modifiedUpdateSalesVolume),
                                                        this);
    df_UpdateSalesVolumeGLB.registerOverrideMethod(     methodstr(FormCheckBoxControl, modified),
                                                        methodstr(AVABPJobsUIBuilder, modifiedUpdateSalesVolumeGLB),
                                                        this);
}

/// <summary>
///     AVA <c>modifiedKCS_KBVBuildingProjectID</c> method.
/// </summary>
/// <param name="_df_KCS_KBVBuildingProjectID">
///     <c>FormStringControl</c> as type
/// </param>
/// <returns>
///     <c>boolean</c> as return value
/// </returns>
public boolean modifiedKCS_KBVBuildingProjectID(FormStringControl _df_KCS_KBVBuildingProjectID)
{
    if(_df_KCS_KBVBuildingProjectID.valueStr())
    {
        if(!KCS_KBVBuildingProjectTable::find(_df_KCS_KBVBuildingProjectID.valueStr()).RecId)
        {
            df_KCS_KBVBuildingProjectID.value('');
        }
    }
    return true;
}

